;(globalThis.BangbomChat=globalThis.BangbomChat||{}).theme=`
:host{all:initial;color-scheme:light;--ink:#141714;--sub:#5d625d;--muted:#71746f;--green:#1f6b4f;--line:rgba(20,23,20,.1);--bg:#f7f6f2;--gray:#efede8;font:15px/1.6 "PretendardLocal","Pretendard",system-ui,-apple-system,"Apple SD Gothic Neo","Malgun Gothic",sans-serif;letter-spacing:-.01em;color:var(--ink);position:relative;z-index:var(--bb-z,1000)}*,*:before,*:after{box-sizing:border-box}button,input,select{font:inherit;letter-spacing:inherit}button{cursor:pointer;color:inherit;-webkit-tap-highlight-color:transparent}button:focus-visible,input:focus-visible,select:focus-visible,[tabindex]:focus-visible{outline:2px solid var(--green);outline-offset:2px}button:disabled{opacity:.5;cursor:wait}[hidden]{display:none!important}
.fab{position:fixed;right:max(20px,env(safe-area-inset-right));bottom:max(20px,env(safe-area-inset-bottom));border:0;background:var(--ink);color:#fff;border-radius:999px;height:52px;padding:0 22px;font-weight:600;font-size:15px;box-shadow:0 14px 34px -12px rgba(20,23,20,.5)}
.panel{position:fixed;right:20px;bottom:max(20px,env(safe-area-inset-bottom));width:min(420px,calc(100vw - 40px));height:min(720px,calc(100dvh - 40px));display:flex;flex-direction:column;background:var(--bg);box-shadow:0 30px 80px -24px rgba(20,23,20,.45);border:1px solid var(--line);border-radius:24px;overflow:hidden;isolation:isolate;animation:pin .28s cubic-bezier(.2,.7,.2,1)}@keyframes pin{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:none}}
.panel header{display:flex;align-items:center;gap:12px;background:#fff;color:var(--ink);padding:16px 16px 14px 18px;flex:none;border-bottom:1px solid var(--line)}.mark{position:relative;width:40px;height:40px;display:grid;place-items:center;background:var(--ink);border-radius:50%;color:#fff;font-size:16px;font-weight:700}.mark:after{content:"";position:absolute;right:0;bottom:1px;width:11px;height:11px;border-radius:50%;background:#3fbf7f;border:2px solid #fff}.sub{font-family:Georgia,"Times New Roman",serif;font-style:italic;font-size:13px;line-height:1.3;color:var(--green);letter-spacing:0}.title{font-size:17px;font-weight:700;letter-spacing:-.03em;line-height:1.4}.headspace{flex:1;min-width:0}.icon{color:var(--ink);background:#fff;border:1px solid var(--line);border-radius:999px;padding:0 12px;min-height:36px;font-size:13px;font-weight:600}.icon:hover{background:var(--gray)}.close{width:36px;padding:0;font-size:18px;line-height:1}
.bar{background:#fff;border-bottom:1px solid var(--line);padding:8px 18px 10px;flex:none}.bar button{border:0;background:none;color:var(--green);font-weight:600;font-size:13px;text-align:left;padding:2px 0;line-height:1.5;text-decoration:underline;text-underline-offset:3px}
.log{flex:1;min-height:0;overflow:auto;padding:20px 16px 8px;overscroll-behavior:contain;scrollbar-width:thin}.who,.eyebrow{font-size:12px;font-weight:600;color:var(--sub)}.eyebrow{font-family:Georgia,"Times New Roman",serif;font-style:italic;font-size:13px;color:var(--green);font-weight:400}.msg{margin:0 0 14px;overflow-wrap:anywhere}.msg.me{text-align:right}.bubble{display:inline-block;margin-top:4px;max-width:92%;background:#fff;border:1px solid var(--line);border-radius:6px 18px 18px 18px;padding:11px 14px;font-size:15px;line-height:1.6;text-align:left;white-space:pre-line;word-break:keep-all;box-shadow:0 2px 8px -4px rgba(20,23,20,.12)}.me .bubble{background:var(--ink);color:#fff;border-color:var(--ink);border-radius:18px 6px 18px 18px;box-shadow:none}
.links{display:flex;flex-wrap:wrap;gap:6px;margin-top:8px}.links a{font-size:13px;font-weight:600;color:var(--green);text-decoration:underline;text-underline-offset:3px}.note{display:block;margin-top:6px;font-size:12px;color:var(--muted)}
.choices{display:flex;gap:6px;flex-wrap:wrap;margin:6px 0 14px}.btn{background:#fff;border:1px solid var(--line);color:var(--ink);font-size:14px;font-weight:600;border-radius:999px;min-height:40px;padding:0 15px;text-align:left}.btn:hover{background:var(--gray)}.btn.primary{background:var(--ink);color:#fff;border-color:var(--ink)}.btn.primary:hover{background:#000}
.card,.pair{background:#fff;border:1px solid var(--line);border-radius:20px;padding:16px;margin:10px 0;overflow-wrap:anywhere;box-shadow:0 10px 30px -22px rgba(20,23,20,.4)}.cardtop{display:flex;justify-content:space-between;gap:8px;align-items:center}.tag{font-size:12px;font-weight:600;padding:3px 9px;color:var(--sub);border-radius:999px;background:var(--gray)}.tag.sample{color:#7a4b12;background:#fbf0dc}.card h3{font-size:18px;margin:6px 0 2px;letter-spacing:-.04em;font-weight:700}.number{font-size:16px;font-weight:700;font-variant-numeric:tabular-nums}.small,.source{font-size:13px;color:var(--sub)}.source{font-size:12px;color:var(--muted)}.reason{margin:10px 0;padding:10px 12px;border-radius:12px;background:var(--bg);font-size:13px;color:var(--sub)}.card .choices{margin:10px 0 0}
.composer{background:#fff;border-top:1px solid var(--line);padding:12px 14px max(12px,env(safe-area-inset-bottom));flex:none}.box{display:flex;gap:6px;align-items:center;border:1px solid var(--line);background:var(--bg);border-radius:999px;padding:5px 5px 5px 8px}.box:focus-within{border-color:var(--ink)}.box input{min-width:0;flex:1;background:transparent;border:0;padding:6px 8px;font-size:16px;color:var(--ink)}.box input:focus-visible{outline:0}.send{padding:0 16px;background:var(--ink);color:#fff;border:0;border-radius:999px;font-size:14px;font-weight:600;min-height:38px}.privacy{margin:8px 4px 0;font-size:11px;color:var(--muted);display:flex;flex-wrap:wrap;gap:4px 10px;align-items:center}
.pair strong{font-size:15px}.pair p{font-size:14px;margin:4px 0}.sheet{position:absolute;inset:0;display:flex;flex-direction:column;background:var(--bg)}.sheethead{display:flex;align-items:center;justify-content:space-between;padding:16px 18px;background:#fff;border-bottom:1px solid var(--line)}.sheethead h2{font-size:18px;margin:0;letter-spacing:-.03em}.sheetbody{overflow:auto;padding:16px 18px}.group{border:0;margin:0 0 16px;padding:0}.group legend{font-size:15px;font-weight:700;margin:0 0 6px}.sheet input[type=number],.sheet select{font:inherit;width:100%;height:46px;padding:0 12px;border:1px solid var(--line);border-radius:12px;color:var(--ink);background:#fff}.sheet label{font-size:14px}.notice{white-space:pre-line;color:#8a4a12;font-size:13px}.loader{font-size:13px;color:var(--muted)}
@media(max-width:520px){.panel{bottom:0;right:0;width:100vw;height:min(780px,100dvh);border-radius:22px 22px 0 0;border-bottom:0}.panel header{padding-top:max(14px,env(safe-area-inset-top))}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;animation:none!important}}`;
